// Open-flow board test (Nexys2-500): the Clocking Wizard's module (#793, clkgen.v, generated by core/clocking.js)
// in Verilog: a DCM_SP on the 50 MHz clock (B8) with a fixed phase shift (PHASE_SHIFT 32: 2.5 ns), CLK0 (the
// feedback), CLK90 and CLKFX (25 MHz, x 2 / 4), each on a global buffer, no reset, LOCKED; a counter on each:
//   LD0  CLK0     (bit 24: about 0.67 s per on-off cycle)
//   LD1  CLK90    (bit 24)
//   LD2  CLKFX    (bit 23: about 0.67 s)
//   LD7  LOCKED   (on when the DCM has locked)
// sw[0] = 1 holds the counters.
module top (input clk, input [0:0] sw, output [7:0] led);
  wire clk0, clk90, clkfx, locked;
  reg [24:0] n0 = 0, n90 = 0;
  reg [23:0] nfx = 0;
  reg h0 = 0, h90 = 0, hfx = 0;

  clkgen u_clk (.clk_in(clk), .clk0(clk0), .clk90(clk90), .clkfx(clkfx), .locked(locked));

  // (the switch is synchronised to each clock)
  always @(posedge clk0) begin h0 <= sw[0]; if (!h0) n0 <= n0 + 1; end
  always @(posedge clk90) begin h90 <= sw[0]; if (!h90) n90 <= n90 + 1; end
  always @(posedge clkfx) begin hfx <= sw[0]; if (!hfx) nfx <= nfx + 1; end

  assign led = {locked, 4'b0000, nfx[23], n90[24], n0[24]};
endmodule
